async function handler(input, ctx) {
  const axios = ctx.require("axios");
  const crypto = ctx.require("crypto");

  const source = input || {};
  const basePrompt = typeof source.prompt === "string" ? source.prompt : "";
  const prompt =
    basePrompt.trim() ||
    (typeof source.userMessage === "string" ? source.userMessage.trim() : "");
  if (!prompt) {
    throw new Error("prompt is required");
  }

  const size =
    typeof source.size === "string" && source.size.trim().length
      ? source.size.trim()
      : "1024x1024";
  const quality =
    typeof source.quality === "string" &&
    source.quality.toLowerCase() === "hd"
      ? "hd"
      : "standard";
  const rawCount = Number(source.count ?? source.n ?? 1);
  const count = Math.max(
    1,
    Math.min(Number.isFinite(rawCount) ? rawCount : 1, 4)
  );
  const title =
    typeof source.title === "string" && source.title.trim().length
      ? source.title.trim()
      : "OpenAI Image Set";
  const negativePrompt =
    typeof source.negativePrompt === "string"
      ? source.negativePrompt.trim()
      : undefined;

  const apiKey = ctx.process.env.OPENAI_API_KEY;
  if (!apiKey) {
    throw new Error("OPENAI_API_KEY not configured");
  }

  const payload = {
    model: "gpt-image-1",
    prompt,
    size,
    quality,
    n: count,
    response_format: "b64_json",
    user: ctx.userId || undefined,
  };

  if (negativePrompt) {
    payload.negative_prompt = negativePrompt;
  }

  const response = await axios.post(
    "https://api.openai.com/v1/images/generations",
    payload,
    {
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
      },
      timeout: 120000,
    }
  );

  const images = Array.isArray(response.data?.data)
    ? response.data.data
    : [];

  if (!images.length) {
    throw new Error("OpenAI returned no images");
  }

  const attachments = [];
  for (let index = 0; index < images.length; index++) {
    const entry = images[index];
    const b64 = entry?.b64_json;
    if (!b64 || typeof b64 !== "string") {
      continue;
    }

    const buffer = Buffer.from(b64, "base64");
    if (!buffer.length) {
      continue;
    }

    const hash = crypto.createHash("sha256").update(buffer).digest("hex");

    const asset = await ctx.assets.saveBuffer({
      buffer,
      mime: "image/png",
      filename: `openai-${Date.now()}-${index}.png`,
      subpath: "generated",
    });

    attachments.push({
      assetId: asset.id,
      url: `/assets/${asset.id}`,
      mime: "image/png",
      size: buffer.length,
      hash,
      altText: prompt,
      provider: "openai",
      index,
    });
  }

  if (!attachments.length) {
    throw new Error("Failed to generate image attachments");
  }

  const deliverable = await ctx.deliverables.create({
    title,
    content: `Generated ${attachments.length} image(s) via OpenAI GPT-Image-1`,
    format: "image/png",
    type: "image",
    attachments: { images: attachments },
    metadata: {
      provider: "openai",
      model: "gpt-image-1",
      prompt,
      size,
      quality,
      count: attachments.length,
      negativePrompt: negativePrompt || null,
    },
  });

  return {
    success: true,
    provider: "openai",
    deliverable,
    images: attachments,
    metadata: {
      prompt,
      size,
      quality,
      count: attachments.length,
    },
  };
}
